'use client'
import { createContext, useRef, useState, type Dispatch, type ReactNode, type SetStateAction } from 'react'

// A site's top navigation (shadcn's navigation menu): a row of triggers and links in DM Sans Medium, each trigger
// opening a panel of links in the card's #262626 fill under it (NavigationMenuItem with NavigationMenuLink rows). Under
// a pointer a panel opens after a short wait and closes a moment after the pointer leaves both; while one is open,
// pointing at another trigger switches at once. A click toggles it; Enter, Space or Down opens it at once with focus on
// its first link; Left and Right move along the triggers; Escape closes it and returns focus. The chevron stays still.
export interface NavigationMenuContextValue {
  active: string | null
  setActive: Dispatch<SetStateAction<string | null>>
  /** The triggers and links of the row, in order, for Left and Right. */
  row: () => HTMLElement[]
}
export const NavigationMenuContext = createContext<NavigationMenuContextValue | null>(null)

export interface NavigationMenuProps {
  /** The navigation's name for assistive tech. */
  label?: string
  /** NavigationMenuItem elements. */
  children?: ReactNode
  className?: string
}

export function NavigationMenu({ label = 'Main', children, className }: NavigationMenuProps) {
  const [active, setActive] = useState<string | null>(null)
  const list = useRef<HTMLUListElement | null>(null)
  const row = () => [...(list.current?.querySelectorAll<HTMLElement>('[data-nav-trigger]') ?? [])]
  return (
    <NavigationMenuContext.Provider value={{ active, setActive, row }}>
      <nav data-ds="navigation-menu" aria-label={label} className={className}>
        <ul ref={list} className="flex flex-wrap items-center gap-1">{children}</ul>
      </nav>
    </NavigationMenuContext.Provider>
  )
}

export default NavigationMenu

'use client'
import { useContext, useEffect, useId, useRef, type FocusEvent, type KeyboardEvent, type MouseEvent, type PointerEvent, type ReactNode } from 'react'
import { ChevronDown } from 'lucide-react'
import { NavigationMenuContext } from '@/react/components/ui/NavigationMenu'
import { PopoverPanel } from '@/react/components/ui/PopoverPanel'
import { firstFocusable, usePopover } from '@/react/hooks/usePopover'
import { cn } from '@/react/lib/cn'

// One entry of a NavigationMenu: with children, a trigger and its panel of links (NavigationMenuLink); with `href` and
// no children, a plain link in the row (`active` for the page you are on). The open trigger takes the #262626 fill.
export interface NavigationMenuItemProps {
  /** The trigger's or the link's text. */
  label: string
  /** A plain link in the row, when it has no panel. */
  href?: string
  /** The page you are on (a plain link). */
  active?: boolean
  /** The panel's width (a CSS length). */
  width?: string
  /** The panel's links. */
  children?: ReactNode
}

const WAIT = 80 // the site's menu intent (--dur-menu-intent)
const GRACE = 240 // the site's menu grace (--dur-menu-grace)
const ROW = 'inline-flex h-control-md cursor-pointer items-center gap-1.5 rounded-control px-4 type-ui-strong -outline-offset-2 transition-[background-color,color] duration-160 ease-standard max-md:h-control-touch'

export function NavigationMenuItem({ label, href, active, width = '400px', children }: NavigationMenuItemProps) {
  const nav = useContext(NavigationMenuContext)!
  const key = useId()
  const pop = usePopover({ side: 'bottom', align: 'start', gap: 8 })
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const hovered = useRef(0)

  useEffect(() => {
    if (pop.open) nav.setActive(key)
    else nav.setActive((a) => (a === key ? null : a))
  }, [pop.open]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (nav.active !== key && pop.open) pop.hide(false, true)
  }, [nav.active]) // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => clearTimeout(timer.current), [])

  function move(event: KeyboardEvent) {
    if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return false
    event.preventDefault()
    const row = nav.row()
    const at = row.indexOf(event.currentTarget as HTMLElement)
    row[(at + (event.key === 'ArrowRight' ? 1 : -1) + row.length) % row.length]?.focus()
    return true
  }

  if (!children) {
    return (
      <li data-ds="navigation-menu-item" className="flex">
        <a data-nav-trigger="" href={href} aria-current={active ? 'page' : undefined} className={cn(ROW, active ? 'text-fg' : 'text-fg-soft hover:bg-action-ghost-hover hover:text-fg')} onKeyDown={move}>{label}</a>
      </li>
    )
  }

  async function openAt(keyboard: boolean, focus: boolean) {
    clearTimeout(timer.current)
    await pop.show({ keyboard })
    if (focus) (firstFocusable(pop.panel.current) ?? pop.panel.current)?.focus({ preventScroll: true })
  }
  function enter(event: PointerEvent) {
    if (event.pointerType !== 'mouse') return
    clearTimeout(timer.current)
    if (pop.open) return
    // Another panel open: switch at once.
    if (nav.active && nav.active !== key) {
      hovered.current = Date.now()
      return void openAt(true, false)
    }
    // ds-latency: the wait keeps a passing pointer from opening it.
    timer.current = setTimeout(() => {
      hovered.current = Date.now()
      void openAt(false, false)
    }, WAIT)
  }
  function leave(event: PointerEvent) {
    if (event.pointerType !== 'mouse') return
    clearTimeout(timer.current)
    // ds-latency: a grace to cross the gap into the panel.
    timer.current = setTimeout(() => pop.hide(), GRACE)
  }
  // A click toggles it; a click right after the pointer opened it keeps it open.
  function onClick(event: MouseEvent) {
    const keyboard = event.detail === 0
    if (pop.open) {
      if (!keyboard && Date.now() - hovered.current < 400) return
      pop.hide(keyboard, keyboard)
    }
    else void openAt(keyboard, keyboard)
  }
  function onKey(event: KeyboardEvent) {
    if (move(event)) return
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      void openAt(true, true)
    }
  }
  function onBlur(event: FocusEvent) {
    const next = event.relatedTarget as Node | null
    if (next && !pop.panel.current?.contains(next) && !pop.anchor.current?.contains(next)) pop.hide()
  }
  return (
    <li data-ds="navigation-menu-item" className="flex" onPointerEnter={enter} onPointerLeave={leave}>
      <button
        data-nav-trigger=""
        ref={(el) => { pop.anchor.current = el }}
        type="button"
        aria-expanded={pop.open}
        className={cn(ROW, 'text-fg-soft hover:not-aria-expanded:bg-action-ghost-hover hover:text-fg aria-expanded:bg-action-secondary aria-expanded:text-fg')}
        onClick={onClick}
        onKeyDown={onKey}
        onBlur={onBlur}
      >
        {label}
        <ChevronDown size={16} strokeWidth={1.5} aria-hidden="true" className="shrink-0 text-fg-muted" />
      </button>
      <PopoverPanel data-ds="navigation-menu-item" pop={pop} aria-label={label} tabIndex={-1} className="p-2" style={{ width }} onPointerEnter={enter} onPointerLeave={leave}>
        {children}
      </PopoverPanel>
    </li>
  )
}

export default NavigationMenuItem

import type { AnchorHTMLAttributes, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// A link in a NavigationMenuItem's panel: its title in DM Sans Medium and a muted line under it, the small corner; the
// link under the pointer or focus takes the #262626 fill. Other props (onClick) land on the <a>.
export interface NavigationMenuLinkProps extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'title'> {
  href?: string
  /** The link's title. */
  title: string
  /** A line under it. */
  description?: string
  children?: ReactNode
}

export function NavigationMenuLink({ href, title, description, className, ...rest }: NavigationMenuLinkProps) {
  return (
    <a data-ds="navigation-menu-link" href={href} className={cn('flex flex-col gap-1 rounded-ds-sm p-3 -outline-offset-2 transition-[background-color] duration-160 ease-standard hover:bg-action-secondary focus-visible:bg-action-secondary', className)} {...rest}>
      <span className="type-ui-strong text-fg">{title}</span>
      {description && <span className="type-caption text-fg-muted">{description}</span>}
    </a>
  )
}

export default NavigationMenuLink

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

